snippet.History.swift:
public struct History<Element> {
    final class Node {
        let element: Element
        var next: Node?
        init(_ element: Element,_ next: Node?) { self.element = element; self.next = next }
        deinit {
            // Release uniquely owned tails iteratively.
            var current = next; next = nil
            while var node = current {
                current = nil
                guard isKnownUniquelyReferenced(&node) else { break }
                current = node.next; node.next = nil
            }
        }
    }
    var head: Node?
    public init() {}
    public mutating func append(_ element: Element) { head = Node(element,head) }
    public var count: Int { var n = 0, node = head; while let x = node { n += 1; node = x.next }; return n }
}

snippet.main.swift:
var a = History<Int>()
for i in 0..<5 { a.append(i) }
var b = a; b.append(99)
b = History()                      // the walk must stop at a's shared head
print("older kept:", a.count, "(expected 5)")
a = History()
print("released")
